import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../services/database_service.dart';
import '../models/intervention.dart';
class HistoryScreen extends StatefulWidget{final String enterprise;const HistoryScreen({super.key,required this.enterprise});@override State<HistoryScreen> createState()=>_HistoryScreenState();}
class _HistoryScreenState extends State<HistoryScreen>{late Future<List<Intervention>> future;@override void initState(){super.initState();future=DatabaseService.instance.all(widget.enterprise);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Historique des interventions')),body:FutureBuilder<List<Intervention>>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('Erreur : ${s.error}'));final rows=s.data??[];if(rows.isEmpty)return const Center(child:Text('Aucune intervention enregistrée.'));return ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final x=rows[i];return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ExpansionTile(leading:const Icon(Icons.sensors),title:Text('PDL : ${x.pdl}'),subtitle:Text(DateFormat('dd/MM/yyyy HH:mm').format(DateTime.tryParse(x.createdAt)??DateTime.now())),children:[ListTile(title:const Text('Détecteur CO 1'),subtitle:Text(x.detector1)),ListTile(title:const Text('Détecteur CO 2'),subtitle:Text(x.detector2)),ListTile(title:const Text('Coordonnées GPS'),subtitle:Text('${x.latitude}, ${x.longitude}'))]));});}));}
